// Auxiliary fixture: constraints generated by Tcl (variables, expr,
// lists, foreach) rather than written out one command per line
// (rtl-buddy-cdc#331).
//
// Three asynchronous clocks in a ring, every hop through a 2FF
// synchroniser: clk_a → clk_b → clk_c → clk_a. The SDC declares none of
// it literally. A clock table (a Tcl list of name / period pairs) drives
// a foreach that emits each create_clock and collects one -group per
// clock into a list, expanded into a single set_clock_groups with {*};
// a second foreach types the data inputs with set_input_delay at
// [expr {0.1 * $period}].
//
// tcl backend: the file is evaluated, so the SDC declares three clocks
// in three async groups and two typed inputs. Three async crossings, all
// 2FF: clean.
// tokenizer backend: $var, expr and foreach are not evaluated, so the
// file declares nothing. Its verdict is pinned separately by the test:
// see tests/test_sdc_variety_fixtures.py.
//
//   clk_a ──2FF──▶ clk_b ──2FF──▶ clk_c ──2FF──▶ clk_a

module tcl_generated_constraints (
    input  logic clk_a,
    input  logic clk_b,
    input  logic clk_c,
    input  logic rst_n,
    input  logic d_a,
    input  logic d_b,
    output logic q_a,
    output logic q_c
);

    logic a_q, a_s1, a_s2, b_s1, b_s2, b_q, c_s1, c_s2, c_q;

    // clk_a: source register, and the 2FF synchroniser from clk_c.
    always_ff @(posedge clk_a or negedge rst_n) begin
        if (!rst_n) begin
            a_q  <= 1'b0;
            a_s1 <= 1'b0;
            a_s2 <= 1'b0;
        end else begin
            a_q  <= d_a;
            a_s1 <= c_q;
            a_s2 <= a_s1;
        end
    end
    assign q_a = a_s2;

    // clk_b: 2FF synchroniser from clk_a, then a register.
    always_ff @(posedge clk_b or negedge rst_n) begin
        if (!rst_n) begin
            b_s1 <= 1'b0;
            b_s2 <= 1'b0;
            b_q  <= 1'b0;
        end else begin
            b_s1 <= a_q;
            b_s2 <= b_s1;
            b_q  <= b_s2 ^ d_b;
        end
    end

    // clk_c: 2FF synchroniser from clk_b, then a register.
    always_ff @(posedge clk_c or negedge rst_n) begin
        if (!rst_n) begin
            c_s1 <= 1'b0;
            c_s2 <= 1'b0;
            c_q  <= 1'b0;
        end else begin
            c_s1 <= b_q;
            c_s2 <= c_s1;
            c_q  <= ~c_s2;
        end
    end
    assign q_c = c_q;

endmodule
